// Writes the CampaignPayments ABI from the Foundry artifact into a typed module.
// Usage: npm run contracts:build && npm run contracts:abi
import { readFileSync, writeFileSync } from "node:fs";

const artifact = JSON.parse(readFileSync("contracts/out/CampaignPayments.sol/CampaignPayments.json", "utf8"));
const out = `// Generated by scripts/export-abi.mjs from contracts/out/CampaignPayments.sol/CampaignPayments.json.
// Do not edit by hand: change the contract, rebuild, and re-export.
export const campaignPaymentsAbi = ${JSON.stringify(artifact.abi, null, 2)} as const;
`;
writeFileSync("src/lib/contracts/campaign-payments-abi.ts", out);
console.log(`Exported ${artifact.abi.length} ABI entries.`);
